D={
80217:("Direções","Para direções: **Go straight. Turn left. Turn right.** Referência: **at the corner, on the street.** Imperativo: verbo sozinho.",[("{{Go straight}} on this street.","Siga em frente nesta rua."),("{{Turn left}} at the corner.","Vire à esquerda na esquina."),("{{Turn right}}.","Vire à direita."),("The station is there.","A estação fica ali.")],"“Vire à direita”:",["Turn right.","Go right turn.","Right go."],0,"Turn right."),
80218:("Which way?","**Which way is the park?** Resposta: **This way. / That way.** *Near* = perto, *far* = longe.",[("{{Which way}} is the park?","Qual é o caminho do parque?"),("{{This way}}.","Por aqui."),("{{That way}}.","Por ali."),("It's not far.","Não é longe.")],"“Por ali”:",["That way.","This way.","Near way."],0,"That way = longe."),
80219:("Movimento: past, over, under","**Past** = passando por. **Over** = por cima. **Under** = por baixo. **Through** = através. *Go through the tunnel.*",[("Go {{past}} the railway.","Passe pela ferrovia."),("Go {{over}} the bridge.","Atravesse a ponte."),("Go {{under}} the arch.","Passe por baixo do arco."),("Go {{through}} the tunnel.","Atravesse o túnel.")],"“Através”:",["through","over","past"],0,"Through."),
80220:("Onde fica?","Preposições de lugar: **beside** (ao lado), **behind** (atrás), **between** (entre). *The bank is beside the pharmacy.*",[("The bank is {{beside}} the pharmacy.","O banco fica ao lado da farmácia."),("The library is {{behind}} the bank.","A biblioteca fica atrás do banco."),("It's {{between}} the two shops.","Fica entre as duas lojas."),("Where is it?","Onde fica?")],"“Entre”:",["between","behind","beside"],0,"Between."),
910027:("Come back, go back","**Come back** = voltar (para onde estou). **Go back** = voltar (para lá). **Get back** = regressar. *Come back soon!*",[("{{Come back}} soon!","Volte logo!"),("I {{go back}} home.","Volto para casa."),("We {{get back}} at six.","Voltamos às seis."),("Make a u-turn.","Faça um retorno.")],"“Volte logo”:",["Come back soon!","Back come soon!","Go soon come!"],0,"Come back."),
80221:("Seguir instruções","Siga o mapa: **Walk north. Turn at the tree. Go to the island.** Sequência com **then**: *Go north, then turn left.*",[("{{Walk}} north.","Caminhe para o norte."),("{{Turn}} at the tree.","Vire na árvore."),("{{Then}} go to the island.","Depois vá à ilha."),("Find the treasure!","Encontre o tesouro!")],"“Depois” indica…",["a ordem","o motivo","a negação"],0,"Then = ordem."),
80222:("Horários de transporte","Status: **on time** (no horário), **delayed** (atrasado), **cancelled** (cancelado), **early/late**. *The train is delayed.*",[("The train is {{on time}}.","O trem está no horário."),("The bus is {{delayed}}.","O ônibus está atrasado."),("The flight is {{cancelled}}.","O voo foi cancelado."),("It's from platform two.","Sai da plataforma dois.")],"“Atrasado” (transporte):",["delayed","on time","early"],0,"Delayed."),
80223:("No ônibus","No ônibus: **The next stop is…** **Press the bell. Get off here.** *Fare* = tarifa.",[("{{The next stop is}} Main Street.","A próxima parada é Main Street."),("{{Press the bell}}.","Aperte a campainha."),("{{Get off}} here.","Desça aqui."),("Have your fare ready.","Deixe a tarifa pronta.")],"“Descer do ônibus”:",["get off","get down","go out"],0,"Get off."),
80224:("Is there… nearby?","**Is there a pharmacy nearby?** Resposta: **Yes, there is. It's around here.** *Nearby* = por perto.",[("{{Is there}} a pharmacy {{nearby}}?","Há uma farmácia por perto?"),("Yes, {{there is}}.","Sim."),("It's {{around here}}.","É por aqui."),("No, {{there isn't}}.","Não.")],"“Há um hospital por perto?”",["Is there a hospital nearby?","Is hospital nearby there?","There hospital?"],0,"Is there…?"),
80225:("No carro","No carro: **Fasten your seat belt. The road is bumpy.** Adjetivos: **slow / fast / bumpy**. *Open the window.*",[("{{Fasten}} your seat belt.","Aperte o cinto."),("The road {{is bumpy}}.","A estrada é esburacada."),("We drive {{slow}}.","Dirigimos devagar."),("{{Open}} the window.","Abra a janela.")],"“Aperte o cinto”:",["Fasten your seat belt.","Close belt you.","Belt tighten."],0,"Fasten."),
80226:("No posto","No posto: **Fill it up!** = encha o tanque. **Gas** (EUA) = gasolina. *How much is the gas? I pay in cash.*",[("{{Fill it up}}, please.","Encha o tanque, por favor."),("{{How much}} is the gas?","Quanto custa a gasolina?"),("The tank is {{empty}}.","O tanque está vazio."),("I pay {{in cash}}.","Pago em dinheiro.")],"“Encher o tanque”:",["fill it up","load it full","put it all"],0,"Fill it up."),
80227:("Descrever lugares","Descrição: **It is quiet. The people are friendly.** *There is a church. There are small shops.* Singular is, plural are.",[("The town {{is}} quiet.","A cidade é tranquila."),("The neighbors {{are}} friendly.","Os vizinhos são simpáticos."),("{{There is}} a church.","Há uma igreja."),("{{There are}} small shops.","Há lojas pequenas.")],"Complete: “The people ___ friendly.”",["is","are","be"],1,"people = plural."),
80228:("May I…?","**May I use your phone?** Resposta: **Of course. / Sure. / Sorry, no.** **May** é mais formal que **Can**.",[("{{May I}} use your phone?","Posso usar seu telefone?"),("{{Of course}}!","Claro!"),("{{Sorry}}, the battery is dead.","Desculpe, a bateria acabou."),("Here's a charger.","Aqui está um carregador.")],"Mais formal:",["May I","Can I","Do I"],0,"May I."),
910028:("Sorry, my bad!","Informal: **My bad!** = foi mal! **Oops!** = ops! Formal: **I apologize.** *I'm sorry about that.*",[("{{My bad}}!","Foi mal!"),("{{Oops}}!","Ops!"),("{{I apologize}}.","Peço desculpas."),("It was my fault.","Foi minha culpa.")],"Informal para desculpa:",["My bad!","Sir apologize.","Do sorry."],0,"My bad."),
80229:("Borrow ou lend","**Borrow** = pegar emprestado. **Lend** = emprestar (a alguém). *May I borrow your pen? Can you lend me a book?*",[("{{Can I borrow}} your pen?","Posso pegar sua caneta emprestada?"),("{{Can you lend}} me an umbrella?","Pode me emprestar um guarda-chuva?"),("I'll {{return}} it tomorrow.","Devolvo amanhã."),("Thank you!","Obrigado!")],"Quem pede emprestado usa…",["borrow","lend","return"],0,"Borrow."),
80230:("Could I…?","**Could I try it on?** **Could** é mais educado que **can**. Provador: *fitting room.* Tamanho: **too big / too small / perfect**.",[("{{Could I}} try it on?","Posso provar?"),("It's {{too big}}.","É grande demais."),("It's {{too small}}.","É pequeno demais."),("It's {{perfect}}!","É perfeito!")],"“Grande demais”:",["too big","very big no","enough big"],0,"Too big."),
80231:("Can you…?","Pedir ajuda: **Can you lend a hand? Can you carry this?** **Lend a hand** = dar uma mão (ajudar).",[("{{Can you}} lend a hand?","Pode dar uma mão?"),("{{Can you}} carry this?","Pode carregar isto?"),("It's heavy.","É pesado."),("Sure, I can.","Claro, posso.")],"Idiom para pedir ajuda:",["lend a hand","give hand","take a hand"],0,"Lend a hand."),
80232:("May I…?","Pedir licença no trabalho: **May I leave early? May I go to the doctor?** Resposta: **Yes, you may. / No, I'm sorry.**",[("{{May I}} leave early?","Posso sair mais cedo?"),("{{Yes, you may}}.","Sim, pode."),("I have a doctor's appointment.","Tenho consulta médica."),("See you tomorrow.","Até amanhã.")],"“Posso sair mais cedo?”",["May I leave early?","I may leave early?","May leave I early?"],0,"May I…?"),
80233:("Don't forget","Negativa: **Don't forget your keys!** Para lembrar: **Remember to lock the door.** *Remember + to + verbo.*",[("{{Don't forget}} your keys!","Não esqueça as chaves!"),("{{Remember to}} lock the door.","Lembre-se de trancar a porta."),("I have a reminder.","Tenho um lembrete."),("Where's my wallet?","Onde está minha carteira?")],"“Lembre-se de…”:",["Remember to …","Remember …ing","Don't …"],0,"Remember to."),
80234:("Oops, my fault","Erros: **Oops! My fault. I made a mistake.** Para consertar: **I'll fix it.** *Spill* = derramar, *broken* = quebrado.",[("{{Oops}}! My fault.","Ops! Foi minha culpa."),("I {{made a mistake}}.","Cometi um erro."),("I {{spilled}} the juice.","Derramei o suco."),("{{I'll fix it}}.","Vou consertar.")],"“Cometer um erro”:",["make a mistake","do a mistake","take a mistake"],0,"make a mistake."),
80235:("Could you…?","Pedido educado: **Could you hang the shirts?** *Could you* + verbo base. Responda: **Sure.** / **Of course.**",[("{{Could you}} hang the shirts?","Você poderia pendurar as camisas?"),("{{Could you}} fold the laundry?","Poderia dobrar a roupa?"),("{{Sure}}.","Claro."),("Use the hanger.","Use o cabide.")],"Mais educado:",["Could you help?","You help?","Help me."],0,"Could you…?"),
80236:("Can, can't, must","**Can** = pode. **Can't** = não pode. **Must** = deve. *You can't park here. You must pay a fine.*",[("You {{can't}} park here.","Você não pode estacionar aqui."),("You {{can}} park there.","Você pode estacionar ali."),("You {{must}} follow the sign.","Você deve seguir a placa."),("There's a fine.","Há multa.")],"“Não é permitido”:",["can't","must","can"],0,"Can't."),
910029:("Feel good, feel bad","**Feel** + adjetivo: *I feel cheerful. He feels grumpy.* Positivo: **cheerful, amused**. Negativo: **grumpy, uneasy, annoyed**.",[("I {{feel}} cheerful.","Estou alegre."),("He {{feels}} grumpy.","Ele está rabugento."),("She {{feels}} uneasy.","Ela está inquieta."),("They look annoyed.","Eles parecem irritados.")],"Oposto de cheerful:",["grumpy","amused","happy"],0,"Grumpy."),
80237:("Keep the change","**Keep the change** = fique com o troco. **Tip** = gorjeta. *The service was great, so I leave a tip.*",[("{{Keep the change}}.","Fique com o troco."),("The {{service}} was great.","O serviço foi ótimo."),("I leave a {{tip}}.","Deixo gorjeta."),("Here's the receipt.","Aqui está o recibo.")],"“Gorjeta”:",["tip","bill","change"],0,"Tip."),
80238:("Where does it hurt?","**Where does it hurt?** Resposta: **My head hurts. / It hurts here.** Verbo **hurt** não muda no presente.",[("{{Where does it hurt}}?","Onde dói?"),("{{My head hurts}}.","Minha cabeça dói."),("{{My stomach hurts}}.","Meu estômago dói."),("{{It hurts here}}.","Dói aqui.")],"“Meu braço dói”:",["My arm hurts.","I hurt arm.","Arm does hurt me."],0,"My arm hurts."),
80239:("Ache","**Ache** = dor persistente: **a backache, a headache, a toothache.** *My back aches.* **Hurt** para dor localizada.",[("{{My back aches}}.","Minhas costas doem."),("I have {{a backache}}.","Estou com dor nas costas."),("My shoulder hurts.","Meu ombro dói."),("Rest your knee.","Descanse o joelho.")],"“Dor de dente”:",["toothache","teethache","toothhurt"],0,"Toothache."),
80240:("Have + sintoma","Sintomas: **I have a cold. I have a runny nose. I have a sore throat.** Não use *be* para doenças: **have**.",[("I {{have a cold}}.","Estou resfriado."),("She {{has a runny nose}}.","Ela está com o nariz escorrendo."),("He {{has a sore throat}}.","Ele está com dor de garganta."),("Drink some tea.","Beba um chá.")],"“Estou gripado”:",["I have the flu.","I am flu.","I do flu."],0,"have + doença."),
80241:("Gripe e febre","Gripe: **have the flu, have a fever, have chills.** *Take your temperature.* Descanso: **stay in bed.**",[("I {{have the flu}}.","Estou com gripe."),("He {{has a fever}}.","Ele está com febre."),("She {{has chills}}.","Ela está com calafrios."),("{{Stay in bed}}.","Fique de cama.")],"“Febre”:",["fever","chills","cough"],0,"Fever."),
80242:("Doses","Dose: **Take two drops. Take one tablet.** **Take** + quantidade. Com colher: **one spoon of syrup**.",[("{{Take}} two drops.","Tome duas gotas."),("{{Take}} one tablet.","Tome um comprimido."),("{{Drink}} some water.","Beba água."),("One spoon of syrup.","Uma colher de xarope.")],"“Tome um comprimido”:",["Take one tablet.","Eat tablet one.","Do a tablet."],0,"Take."),
80243:("Imperativos de movimento","Exercícios: **Bend your knees. Stretch. Breathe slowly.** Imperativo: verbo + parte do corpo. *Slowly* = devagar.",[("{{Bend}} your knees.","Dobre os joelhos."),("{{Stretch}} your arms.","Estique os braços."),("{{Breathe}} slowly.","Respire devagar."),("{{Jump}} up!","Pule!")],"“Respire fundo”:",["Breathe in.","Breathing deep.","You breathe."],0,"Imperativo."),
80244:("Frio e calor","Temperatura: **freezing** (congelante), **cold, chilly, cool, warm, hot, boiling** (fervendo). *It's boiling today!*",[("It's {{freezing}}!","Está congelando!"),("It's {{chilly}}.","Está friozinho."),("It's {{warm}}.","Está morno."),("It's {{boiling}}!","Está fervendo!")],"Mais quente que hot:",["boiling","cool","chilly"],0,"Boiling."),
910030:("Have a cold","Doenças e sintomas: **have a cold, have a fever, have a headache.** Para sentir: **feel nauseous.** *Use a thermometer.*",[("I {{have a cold}}.","Estou resfriado."),("She {{has a fever}}.","Ela está com febre."),("He {{feels nauseous}}.","Ele sente enjoo."),("Take your temperature.","Meça a temperatura.")],"“Estou com febre”:",["I have a fever.","I am fever.","I fever have."],0,"have a fever."),
}
